&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차 및 안내 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류전형 - 전화면접 - 대면(화상)면접 – 최종 합격&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;참고 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;고용형태는 정규직으로 수습기간 12주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다. &amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;개인정보 처리방침&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;12&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;/span&gt;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.coupang.jobs/kr/privacy-policy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류 반환 정책&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본&lt;/span&gt;&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;고지는 『채용절차의공정화에관한법률&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;』&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;제11조제6항에 따른 것 입니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;위2항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (recruitingops@coupangfinancial.com&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다. &amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;당사는 위2항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;%1.&quot; data-font=&quot;&quot; data-listid=&quot;13&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[65533,0],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;%1.&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;단, 위 1항 내지 4항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ol&gt;

anthemis-tide:greenhouse:7504908003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;A&lt;/strong&gt;&lt;strong&gt;BOUT TIDE&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;At Tide, we help SMEs save time and money in the running of their businesses by not only offering business accounts and related banking services, but also a comprehensive set of highly usable and connected administrative solutions, from invoicing to accounting.&lt;/p&gt;
&lt;p&gt;Tide is transforming the small business banking market and now supports over 2 million members globally across the UK, India, Germany and France.&lt;/p&gt;
&lt;p&gt;Using advanced technology, all solutions are designed with SMEs in mind. With quick onboarding, low fees and innovative features, we thrive on making data driven decisions to serve our mission: to help SMEs save time and money so they can get back to doing what they love.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Tide facts:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Tide is available for UK, Indian, German and French SMEs&lt;/li&gt;
&lt;li&gt;Over 2 million members: 900,000 UK and 1,100,000 in India and growing rapidly&lt;/li&gt;
&lt;li&gt;Over $300 million raised in funding&lt;/li&gt;
&lt;li&gt;Over 2,800 Tideans globally&lt;/li&gt;
&lt;li&gt;Recognised with Great Place to Work certification three years in a row, and among India’s Top 50 Best Workplaces in Banking, Financial Services, and Insurance in 2026&lt;/li&gt;
&lt;li&gt;We have offices in Central London, with a member support and technology centre in Sofia, Bulgaria, technology centres in Serbia, Romania, Lithuania and Hyderabad and offices in Gurugram, New Delhi, Berlin, Paris and Luxembourg&lt;/li&gt;
&lt;/ul&gt;&lt;/div&gt;&lt;h3&gt;ABOUT THE ROLE&lt;/h3&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Hire and closely manage the DST/FOS team in the assigned market, including training, performance tracking, and providing on-ground support to ensure effective execution.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Identify and engage with SMEs, corporates, restaurants, salons, hotels, and other relevant retail outlets in the Delhi NCR region to pitch and close partnerships for Tide Card distribution.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Take full ownership of the acquisition pipeline by managing both active and prospective leads, ensuring timely follow-ups and conversions.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Collaborate with internal stakeholders to ensure smooth onboarding of new partners across restaurant, salon, retail, and hospitality segments.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Provide ongoing support and training to onboarded partners, equipping them with product knowledge and relevant business opportunities for success.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Coordinate the monthly rollout of partner activation campaigns and app-based marketing initiatives in collaboration with internal teams.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Act as the primary point of contact for partners, handling operational and technical queries and escalating to internal teams for timely resolution.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Explore and implement new growth opportunities by deepening engagement with existing and potential partners.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Monitor the competitive landscape and evolving partner trends to refine strategies and maintain strong market positioning.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;WHAT WE ARE LOOKING FOR&lt;/h3&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;5+ years of total work experience with at least 3+ years managing FOS/Card sales teams, preferably in fintech or prepaid card sales.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Skilled in hiring, training, and scaling field sales teams from scratch with a deep understanding of on-ground execution.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Comfortable working in a fast-paced startup environment and capable of identifying innovative use cases for Tide Card adoption.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Strong ownership mindset with a creative and solutions-driven approach to solving business challenges.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Excellent communication and interpersonal skills for building effective relationships across internal and external stakeholders.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Willingness to engage in fieldwork and use grassroots-level insights to shape regional strategy.&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Self-starter with a detail-oriented work ethic who can work independently and takes initiative without constant supervision&lt;strong data-stringify-type=&quot;bold&quot;&gt;.&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;WHAT YOU’LL GET IN RETURN&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Competitive salary&lt;/li&gt;
&lt;li&gt;Self &amp;amp; Family Health Insurance&lt;/li&gt;
&lt;li&gt;Term &amp;amp; Life Insurance&lt;/li&gt;
&lt;li&gt;OPD Benefits&lt;/li&gt;
&lt;li&gt;Mental wellbeing through Plumm&lt;/li&gt;
&lt;li&gt;Learning &amp;amp; Development Budget&lt;/li&gt;
&lt;li&gt;15 days of Privilege leaves&lt;/li&gt;
&lt;li&gt;12 days of Casual leaves&lt;/li&gt;
&lt;li&gt;12 days of Sick leaves&lt;/li&gt;
&lt;li&gt;3 paid days off for volunteering or L&amp;amp;D activities&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;TIDE IS A PLACE FOR EVERYONE&lt;/h3&gt;
&lt;p&gt;At Tide, we believe that we can only succeed if we let our differences enrich our culture. Our Tideans come from a variety of backgrounds and experience levels. We consider everyone irrespective of their ethnicity, religion, sexual orientation, gender identity, family or parental status, national origin, veteran, neurodiversity or differently-abled status. We celebrate diversity in our workforce as a cornerstone of our success. Our commitment to a broad spectrum of ideas and backgrounds is what enables us to build products that resonate with our members’ diverse needs and lives.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are One Team and foster a transparent and inclusive environment, where everyone’s voice is heard.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;At Tide, we thrive on diversity, embracing various backgrounds and experiences. We welcome all individuals regardless of ethnicity, religion, sexual orientation, gender identity, or disability. Our inclusive culture is key to our success, helping us build products that meet our members&#39; diverse needs. We are One Team, committed to transparency and ensuring everyone’s voice is heard.&lt;/em&gt;&lt;/p&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;strong&gt;Disclaimer&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;em&gt;It has come to our attention that individuals or agencies are falsely claiming to represent Tide and are reaching out to candidates regarding job opportunities. Please be aware that:&lt;/em&gt;&lt;/div&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;not&lt;/strong&gt;&amp;nbsp;charge any fees at any stage of the recruitment process.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;All official Tide job opportunities are listed exclusively on our&amp;nbsp;&lt;a href=&quot;https://www.tide.co/careers/&quot; target=&quot;_blank&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Careers Page&lt;/strong&gt;&lt;/a&gt;&amp;nbsp;and applications should be submitted through this channel.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Communication from Tide will only come from an official&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;@tide&lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;.co&lt;/strong&gt;&amp;nbsp;email address.&lt;/em&gt;&lt;/li&gt;
&lt;li style=&quot;font-style: italic;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;em&gt;Tide does not work with agencies or recruiters without prior formal engagement, and we do not authorize third parties to make job offers on our behalf.&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;If you are contacted by anyone misrepresenting Tide or requesting payment, please treat it as fraudulent and report it to us immediately at &lt;a href=&quot;mailto:talent@tide.co&quot; target=&quot;_blank&quot;&gt;talent@tide.co&lt;/a&gt;&lt;br&gt;Your safety and trust are important to us, and we are committed to ensuring a fair and transparent recruitment process.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Tide leverages AI to enhance our hiring experience. You can read more about how we use AI in our recruitment process in our &lt;a href=&quot;https://assets.ctfassets.net/3h69mkdgxn20/5MFtWSdG8YLKq3jZkK52NY/3f18633073e6cdbd03bba4b9791c64f4/Using_AI_throughout_the_Hiring_Process.pdf&quot; target=&quot;_blank&quot;&gt;AI Policy&lt;/a&gt;.&lt;/em&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Your personal data will be processed by Tide for recruitment purposes and in accordance with &lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;&lt;a class=&quot;c-link&quot; href=&quot;https://assets.ctfassets.net/3h69mkdgxn20/4TE0uAE3SXomATDVneocNA/aa31893960b4064dd406ad15d029dcd3/Recruitment_Privacy_Notice.pdf&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://assets.ctfassets.net/3h69mkdgxn20/1MYf6q4ZMWugpeaROVETBN/526e9c160a2de03576413c81657c6466/Recruitment_Privacy_Notice__Final_Draft__Sep_2024_.pdf&quot; data-sk=&quot;tooltip_parent&quot;&gt;Tide&#39;s Recruitment Privacy Notice&lt;/a&gt;&lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;.&lt;/em&gt;&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

anthemis-truelayer:greenhouse:4899737101.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;Who we are:&lt;/h2&gt;
&lt;p&gt;TrueLayer is Europe’s fastest-growing Pay by Bank network. We power smarter, safer and faster payments by combining real-time bank payments with financial and identity data. E-commerce, iGaming and Financial Services businesses use our products to onboard new users, accept money and make payouts in seconds, and at scale. Live across 22 countries and with 1 new user joining TrueLayer’s Pay by Bank network every 3 seconds, we’re in a very exciting growth stage. This is why we’re expanding the team across our offices in London, Milan, and Dublin.&lt;/p&gt;
&lt;p&gt;Listed in Sifted as one of the 100 fastest growing start-ups in UK &amp;amp; Ireland, and CNBC’s World Top Fintech Companies, we’re trusted by industry leaders like RyanAir and Just Eat Takeaway for continued innovation within our payment products. To date, we’ve raised over $300 million from world-renowned investors including Stripe, Tiger Global, Northzone, and Tencent. But this is just the beginning.&lt;/p&gt;
&lt;p&gt;We’re looking for people who are excited about joining the Pay by Bank revolution and helping us change the way the world pays. Could this be you?&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;&lt;strong&gt;Description:&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;TrueLayer is expanding its Pay by Bank network in Brazil, and we&#39;re looking for a Customer Service Agent to join our growing team in São Paulo. In this role, you&#39;ll be the first point of contact for our merchant partners and end users, providing timely, accurate, and empathetic support across multiple channels. You&#39;ll play a central role in ensuring a seamless customer experience as TrueLayer scales in one of the world&#39;s most dynamic fintech markets.&lt;/p&gt;
&lt;p&gt;This is an exciting opportunity to join TrueLayer at a pivotal moment in our LatAm expansion, working closely with Product, Engineering, and Compliance teams to resolve issues, surface insights, and help shape the support function from the ground up.&lt;/p&gt;
&lt;p&gt;Location: São Paulo, Brazil (sometimes the team meet up but mostly working remotely)&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;What we expect from you as a Client Operations Specialist:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Handle inbound customer enquiries via email, chat, and phone, resolving issues efficiently and with care&lt;/li&gt;
&lt;li&gt;Diagnose and troubleshoot troubleshoot technical issues, across all of our APIs&lt;/li&gt;
&lt;li&gt;Maintain accurate records of customer interactions and resolutions in our CRM system&lt;/li&gt;
&lt;li&gt;Identify patterns in customer feedback and communicate recurring issues to Product and Engineering teams to drive continuous improvement&lt;/li&gt;
&lt;li&gt;Contribute to the development of help centre content, FAQs, and support documentation in both Brazilian Portuguese and English&lt;/li&gt;
&lt;li&gt;Consistently meet or exceed service level agreements (SLAs) for response time and resolution quality&lt;/li&gt;
&lt;li&gt;Collaborate with cross-functional teams including Product, Engineering, and Compliance to resolve complex cases and improve the end-to-end customer journey&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About you:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Fluent in Brazilian Portuguese (native or near-native); professional proficiency in English&lt;/li&gt;
&lt;li&gt;Previous experience in a customer support, service, or operations role, ideally within fintech, payments, or a technology environment&lt;/li&gt;
&lt;li&gt;Strong written and verbal communication skills, with the ability to explain technical concepts clearly to non-technical audiences&lt;/li&gt;
&lt;li&gt;Comfortable working with CRM and ticketing tools such as Zendesk or similar platforms&lt;/li&gt;
&lt;li&gt;Detail-oriented with strong problem-solving skills and the ability to prioritise effectively in a fast-moving environment&lt;/li&gt;
&lt;li&gt;A collaborative approach and the ability to work across time zones with distributed, international teams&lt;/li&gt;
&lt;li&gt;Familiarity with Brazil&#39;s financial regulatory landscape, including Banco Central do Brasil regulations and PIX&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;We would be particularly excited if you have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience supporting payments, open banking, or financial services products&lt;/li&gt;
&lt;li&gt;Professional proficiency in Spanish, an advantage for supporting wider LatAm operations&lt;/li&gt;
&lt;li&gt;Experience writing or contributing to support documentation or knowledge bases&lt;/li&gt;
&lt;li&gt;Exposure to API or technical integrations – curiosity and the ability to learn technical concepts is what matters most here&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Don&#39;t meet all the requirements?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Multiple studies have shown that women and people of underrepresented groups are sometimes less likely to apply to jobs unless they meet every single requirement. At TrueLayer, we are committed to building a diverse workforce, so if you are excited about this role and have the essential skills, but not the entire checklist – we&#39;d still love to hear from you!&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;What you can expect from us:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Competitive salary and meaningful equity in the company 💰&lt;/li&gt;
&lt;li&gt;Benefits inline with legal requirements for the Brazilian employment act&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About our hiring process:&lt;/strong&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;Initial screen with a member of our Talent team&lt;/li&gt;
&lt;li&gt;First interview with the Support Agent Team Lead - Jonathan&lt;/li&gt;
&lt;li&gt;Skills-based assessment or role-play exercise - TBC&lt;/li&gt;
&lt;li&gt;Final interview with a cross-functional panel - Simon C and one more&lt;/li&gt;
&lt;/ol&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;At TrueLayer, we don’t just do inclusion and diversity. We embrace people that have different opinions, perspectives and personalities. Because we believe that by seeing the world from all sorts of angles, we can make life better for all the people who live in it. We strongly encourage applications from underrepresented groups (e.g. people of colour, the LGBTQ+ community, people with disabilities, neurodivergent people, parents, carers, and people from all socio-economic backgrounds). If you’d like to discuss alternative working patterns, please let us know.&lt;/p&gt;
&lt;div class=&quot;c-message_kit__gutter__right&quot; data-qa=&quot;message_content&quot;&gt;
&lt;div class=&quot;c-message_kit__blocks c-message_kit__blocks--rich_text&quot;&gt;
&lt;div class=&quot;c-message__message_blocks c-message__message_blocks--rich_text&quot; data-qa=&quot;message-text&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer&quot; data-qa=&quot;block-kit-renderer&quot;&gt;
&lt;div class=&quot;p-block_kit_renderer__block_wrapper p-block_kit_renderer__block_wrapper--first&quot;&gt;
&lt;div class=&quot;p-rich_text_block&quot;&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;We will always aim to make appropriate adjustments to ensure we are fully inclusive to people with different needs during our interview process. So if you need us to make any adjustments to suit your individual needs please let us know - we’ll be happy to support you.&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;/div&gt;

baincapitalventures-justworks:greenhouse.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h1&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Justworks, you’ll enjoy a welcoming and casual environment, great benefits, wellness program offerings, company retreats, and the ability to interact with and learn from leaders in the startup community. We work hard and care about our most prized asset - our people.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re helping businesses get off the ground by enabling them to focus on running their business. We solve HR issues. We’re data-driven and never stop iterating. If you’d like to work in a supportive, entrepreneurial environment, are interested in building something meaningful and having fun while doing it, we’d love to hear from you.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We&#39;re united by shared goals and shared motivations at Justworks. These are best summed up in our company values, which are reflected in our product and in our team.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.justworks.com/careers#values&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our Values&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If this sounds like you, you’ll fit right in.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Who You Are: &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You are a customer-focused problem solver who thrives in a fast-paced environment. As the first hire in this function, you are a hands-on practitioner who takes pride in getting things right from day one. You are passionate about the Justworks product and possess the technical curiosity to leverage AI and automation to scale our support as we grow. You are comfortable being &quot;in the weeds&quot; with complex inquiries and enjoy the process of documenting insights to define our standard of excellence for international support.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own the front-line experience for Admins and EOR employees across phone, email, and chat, providing expert guidance on international payroll, benefits, and platform navigation.&lt;/li&gt;
&lt;li&gt;Partner with International Consultants to navigate complex compliance and HR issues, ensuring customers receive holistic, accurate, and high-touch support.&lt;/li&gt;
&lt;li&gt;Serve as the product expert for the Justworks international offering, guiding customers through the platform and ensuring they maximize its value.&lt;/li&gt;
&lt;li&gt;Collaborate cross-functionally with Product, Operations, and Legal to streamline workflows and bridge the gap between customer needs and internal processes.&lt;/li&gt;
&lt;li&gt;Build the foundational knowledge base by creating the initial documentation, FAQs, and standard operating procedures that will serve as the blueprint for the team’s growth.&lt;/li&gt;
&lt;li&gt;Drive AI &amp;amp; Efficiency initiatives by identifying and implementing automation opportunities to improve support speed and accuracy.&lt;/li&gt;
&lt;li&gt;Close the feedback loop by relaying customer insights to Product and Operations teams, directly influencing the international product roadmap.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;How You’ll Do Your Work:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As a Customer Support Specialist, International, &lt;em&gt;how&lt;/em&gt; results are achieved is paramount for your success and ultimately result in our success as an organization. In this role, your foundational knowledge, skills, abilities and personal attributes are anchored in the following competencies:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Consultative&lt;/strong&gt;: takes an approach that focuses on building relationships with others, understanding their problems, and developing solutions to their challenges through open-ended questions and active listening.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Taking responsibility&lt;/strong&gt;: being accountable, being committed, and accepting ownership for one&#39;s decisions, actions, and behavior.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Adaptability&lt;/strong&gt;:&amp;nbsp; the ability to adjust your approach or actions in response to changes in your external environment.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Solution-oriented: &lt;/strong&gt;identifies the source of a question or challenge and provides the right, or a better, way of doing things.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Curious:&lt;/strong&gt; the innate desire to learn, grow and understand.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;In addition, all Justworkers focus on aligning their behaviors to our core values known as COGIS. It stands for:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Camaraderie&lt;/strong&gt; - Day to day you can be seen working together toward a higher purpose. You like to have fun. You’re an active listener, treat people respectfully, and have a strong desire to know and help others.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Openness&lt;/strong&gt; - Your default is to be open. You&#39;re willing to share information, understand other perspectives, and consider new possibilities. You’re curious, ask open questions, and are receptive to thoughts and feedback from others.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Grit &lt;/strong&gt;- You demonstrate grit by having the courage to commit and persevere. You’re committed, earnest, and dive in to get the job done well with a positive attitude.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Integrity&lt;/strong&gt; - Simply put, do what you say and say what you&#39;ll do. You’re honest and forthright, have a strong moral compass, and strive to match your words with your actions while leading by example.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Simplicity&lt;/strong&gt; - Be like Einstein: “Everything should be made as simple as possible, but no simpler.”&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qualifications:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;4+ years experience in a customer-facing role, ideally with experience in the EOR space.&lt;/li&gt;
&lt;li&gt;Proven track record of building new functions or workflows and automating processes for scale.&lt;/li&gt;
&lt;li&gt;Excellent communication, problem-solving, and consultative skills.&lt;/li&gt;
&lt;li&gt;Native or close to native English fluency (written and verbal).&lt;/li&gt;
&lt;li&gt;Experience working with US-based customers and stakeholders.&lt;/li&gt;
&lt;li&gt;A proactive approach to learning and a track record of using new tools (AI, automation, or knowledge systems) to work more efficiently.&lt;/li&gt;
&lt;li&gt;Ability to work independently as an individual contributor while keeping internal teams updated on customer trends.&lt;/li&gt;
&lt;li&gt;Expert-level proficiency with Zendesk, JIRA, or AI-integrated support tools is a plus.&lt;/li&gt;
&lt;li&gt;Experience at a high-growth SaaS company is a plus.&lt;/li&gt;
&lt;li&gt;Experience with leading others in a team-lead or manager capacity is a plus.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The base wage range for this position based in our Mexico City Office is targeted at 600,000 MXN - 750,000 MXN per year (50,000 MXN - 62,500 MXN per month).&lt;/p&gt;
&lt;p&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;#LI-Hybrid #LI-CC1&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Actual compensation is based on multiple factors that are unique to each candidate, including and not limited to skill set, level of relevant experience, and specific work location.&amp;nbsp; &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Salary ranges for positions based in other locations may differ based on the cost of labor in that location.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;For more information about Justworks’ Total Reward Philosophy, including all of the perks and benefits we are proud to offer our team members, please visit &lt;/span&gt;&lt;a href=&quot;https://www.justworks.com/careers#total-reward-philosophy&quot;&gt;Total Rewards @ Justworks&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h1&gt;&lt;strong&gt;Diversity At Justworks&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Justworks is committed to maintaining a workplace where diversity of identity, culture, and life experience is the norm and is celebrated authentically and respected consistently. Diversity in our work, our people, and our product drives creativity and innovation, entrepreneurial leadership and integrity, competitiveness, and collaboration throughout our business and in the market. We depend on our differences to make our team stronger, our workplace more dynamic, and our product accessible to all of our customers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;We’re proud to be an equal opportunity employer open to all qualified applicants regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital or familial status, disability, pregnancy, gender identity or expression, veteran status, genetic information, or any other legally protected status. Justworks is fully dedicated to providing necessary support to candidates with disabilities who may require reasonable accommodations. We also provide reasonable accommodations to employees based on their sincerely held religious beliefs, as well as for other covered reasons consistent with applicable federal, state, and local laws. If you&#39;re in need of a reasonable accommodation, please reach out to us at &lt;a href=&quot;mailto:accommodations@justworks.com&quot;&gt;accommodations@justworks.com&lt;/a&gt;. Your comfort and success matter to us, and we&#39;re here to ensure an inclusive experience.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.justworks.com/press/company-news/justworks-impact-report-2024&quot; target=&quot;_blank&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our DEIB Report&amp;nbsp;&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;

&lt;div class=&quot;content-intro&quot;&gt;&lt;h1&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Justworks, you’ll enjoy a welcoming and casual environment, great benefits, wellness program offerings, company retreats, and the ability to interact with and learn from leaders in the startup community. We work hard and care about our most prized asset - our people.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re helping businesses get off the ground by enabling them to focus on running their business. We solve HR issues. We’re data-driven and never stop iterating. If you’d like to work in a supportive, entrepreneurial environment, are interested in building something meaningful and having fun while doing it, we’d love to hear from you.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We&#39;re united by shared goals and shared motivations at Justworks. These are best summed up in our company values, which are reflected in our product and in our team.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.justworks.com/careers#values&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our Values&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If this sounds like you, you’ll fit right in.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;&lt;strong&gt;About the Role&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;We’re seeking a &lt;strong&gt;Business Development Manager, Strategic Alliances&lt;/strong&gt; responsible for creating and scaling transformative partnerships that go far beyond transactional sales. These alliances will unlock &lt;strong&gt;multi-year revenue streams&lt;/strong&gt;, &lt;strong&gt;new distribution channels&lt;/strong&gt;, and &lt;strong&gt;mutual enterprise value&lt;/strong&gt; between Justworks and our partners.&lt;/p&gt;
&lt;p&gt;This is &lt;strong&gt;not a traditional Account Executive role&lt;/strong&gt; — it’s a strategic position for a &lt;strong&gt;dealmaker and relationship builder&lt;/strong&gt; who can create alignment with &lt;strong&gt;Fortune 1000 companies&lt;/strong&gt;, navigate &lt;strong&gt;complex, consensus-driven sales cycles&lt;/strong&gt;, and drive partnerships that move the needle for both organizations. Typical engagements will involve &lt;strong&gt;long-term, multi-stakeholder cycles (9+ months)&lt;/strong&gt; that require persistence, credibility, and strategic influence.&lt;/p&gt;
&lt;p&gt;You’ll collaborate closely with &lt;strong&gt;Product, Marketing, Legal, and other cross-functional teams&lt;/strong&gt; to transform ideas into scalable business outcomes. From identifying new alliance opportunities to bringing them to market, you will shape how Justworks expands its reach and drives sustainable growth through partnerships that deliver value to small and midsize businesses nationwide.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Who You Are&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;You are a strategic, relationship-driven business development professional who thrives at the intersection of &lt;strong&gt;innovation and execution&lt;/strong&gt;. You bring a &lt;strong&gt;strategic mindset&lt;/strong&gt;, thinking big and long-term while recognizing real-world limitations and pragmatic constraints. You understand how to build partnerships that scale — balancing vision with operational reality.&lt;/p&gt;
&lt;p&gt;The Strategic Alliances team at Justworks focuses on expanding our customer footprint by partnering with &lt;strong&gt;Fortune 1000 companies&lt;/strong&gt; to mutually serve the &lt;strong&gt;SMB segment&lt;/strong&gt;. In this role, you will be responsible for &lt;strong&gt;sourcing, structuring, and launching new partnerships&lt;/strong&gt; that accelerate top-line growth. This includes identifying enterprises with overlapping customer segments, co-developing go-to-market strategies, fostering executive relationships, influencing internal stakeholders, and negotiating high-impact contracts.&lt;/p&gt;
&lt;p&gt;Partnerships at scale are a new muscle for Justworks. You’ll proactively engage with potential partners to uncover their needs, co-create value propositions, and ensure cross-functional alignment across internal teams — from Product to Marketing to Legal — to deliver results for all stakeholders.&lt;/p&gt;
&lt;p&gt;You &lt;strong&gt;set the standard for collaboration&lt;/strong&gt;, with a proven ability to work effectively across functions and levels. You’re as comfortable &lt;strong&gt;rolling up your sleeves to build a pipeline&lt;/strong&gt; as you are &lt;strong&gt;cultivating executive relationships&lt;/strong&gt; at the enterprise level.&lt;/p&gt;
&lt;p&gt;This is a &lt;strong&gt;hybrid role&lt;/strong&gt; based in our &lt;strong&gt;New York City office&lt;/strong&gt;, requiring in-office presence &lt;strong&gt;two days per week&lt;/strong&gt; when not traveling to visit prospective partners.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/h2&gt;
&lt;h3&gt;&lt;strong&gt;Strategic Origination &amp;amp; Deal Management&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Identify, qualify, and pursue &lt;strong&gt;high-potential strategic alliance opportunities&lt;/strong&gt; across priority verticals and geographies.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Develop and tailor &lt;strong&gt;value propositions&lt;/strong&gt; aligned with each partner’s strategic objectives, customer base, and growth priorities.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Collaborate with &lt;strong&gt;Marketing and GTM teams&lt;/strong&gt; to design and execute strategies for acquiring new alliance partners.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Structure, negotiate, and close &lt;strong&gt;complex partnership agreements&lt;/strong&gt;, including co-selling, co-marketing, joint product offerings, or embedded technology integrations.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Build and manage a &lt;strong&gt;robust pipeline&lt;/strong&gt; of prospective partners, maintaining clear visibility into deal stages, timelines, and key stakeholders.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Drive &lt;strong&gt;end-to-end deal management&lt;/strong&gt;, from initial outreach and discovery through contract execution and launch, ensuring alignment with internal priorities and revenue goals.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Enterprise Relationship Development&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Cultivate &lt;strong&gt;trust-based, long-term relationships&lt;/strong&gt; with executive stakeholders at prospective and existing partners.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Serve as a &lt;strong&gt;strategic advisor&lt;/strong&gt;, understanding partner business models, objectives, and constraints to shape win-win collaborations.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Partner cross-functionally with &lt;strong&gt;Product, Marketing, Sales, Legal, and Operations&lt;/strong&gt; to align on partnership goals and deliverables.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Represent Justworks externally with professionalism, credibility, and a deep understanding of our value proposition for SMBs.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Act as the &lt;strong&gt;voice of the partner&lt;/strong&gt; internally, advocating for mutual success and ensuring commitments are delivered on both sides.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Qualifications&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of &lt;strong&gt;enterprise sales, business development, or strategic partnerships&lt;/strong&gt; experience, with a focus on large-scale deal origination and execution.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Proven track record of &lt;strong&gt;closing $5M+ TCV&lt;/strong&gt; and/or &lt;strong&gt;multi-year enterprise deals&lt;/strong&gt; with global Fortune 1000 organizations.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Expertise in managing &lt;strong&gt;complex, consensus-driven sales cycles&lt;/strong&gt; and navigating multiple stakeholder groups.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Strong executive presence, with the ability to build trust and influence at the highest levels.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;li&gt;Strategic thinker who pairs &lt;strong&gt;vision with action&lt;/strong&gt;, balancing innovation with pragmatic execution&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Actual compensation is based on multiple factors that are unique to each candidate, including and not limited to skill set, level of relevant experience, and specific work location.&amp;nbsp; &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Salary ranges for positions based in other locations may differ based on the cost of labor in that location.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;For more information about Justworks’ Total Reward Philosophy, including all of the perks and benefits we are proud to offer our team members, please visit &lt;/span&gt;&lt;a href=&quot;https://www.justworks.com/careers#total-reward-philosophy&quot;&gt;Total Rewards @ Justworks&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h1&gt;&lt;strong&gt;Diversity At Justworks&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Justworks is committed to maintaining a workplace where diversity of identity, culture, and life experience is the norm and is celebrated authentically and respected consistently. Diversity in our work, our people, and our product drives creativity and innovation, entrepreneurial leadership and integrity, competitiveness, and collaboration throughout our business and in the market. We depend on our differences to make our team stronger, our workplace more dynamic, and our product accessible to all of our customers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;We’re proud to be an equal opportunity employer open to all qualified applicants regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital or familial status, disability, pregnancy, gender identity or expression, veteran status, genetic information, or any other legally protected status. Justworks is fully dedicated to providing necessary support to candidates with disabilities who may require reasonable accommodations. We also provide reasonable accommodations to employees based on their sincerely held religious beliefs, as well as for other covered reasons consistent with applicable federal, state, and local laws. If you&#39;re in need of a reasonable accommodation, please reach out to us at &lt;a href=&quot;mailto:accommodations@justworks.com&quot;&gt;accommodations@justworks.com&lt;/a&gt;. Your comfort and success matter to us, and we&#39;re here to ensure an inclusive experience.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.justworks.com/press/company-news/justworks-impact-report-2024&quot; target=&quot;_blank&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our DEIB Report&amp;nbsp;&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;

baincapitalventures-maintainx:greenhouse.descriptionHtml:
&lt;p&gt;MaintainX est la première plateforme mondiale de maintenance et de gestion d&#39;actifs basée sur l&#39;IA, au service de plus de 13 000 clients, dont Duracell, Shell, Cintas et Brenntag. Nous avons levé 150 millions de dollars lors d&#39;un financement de série D mené par Bessemer Venture Partners et Bain Capital Ventures, portant notre financement total à 254 millions de dollars. Nous avons été classés dans le Forbes 2025 Cloud 100, le classement de référence des 100 meilleures entreprises de cloud privé au monde.&lt;/p&gt;
&lt;p&gt;&lt;br&gt;En tant que premier architecte de solutions dédié aux intégrations, vous ferez le lien entre l&#39;équipe des ventes et notre équipe d&#39;intégrations après-vente, en vous assurant que chaque engagement pris envers le client est techniquement viable avant la signature d&#39;un contrat. Vous serez la personne qui transformera des exigences d’intégration vagues en plans clairs et bien délimités que l’équipe de mise en œuvre pourra exécuter dès le premier jour.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Vos missions :&amp;nbsp;&lt;/strong&gt;&lt;br&gt;Collaborer avec les chargés de compte lors des cycles de prévente pour identifier les points faibles techniques et opérationnels liés à la gestion des actifs et au soutien à la maintenance.&lt;br&gt;Mener des entretiens de découverte technique avec les prospects pour comprendre leurs systèmes ERP, GMAO, GIE et autres systèmes d’entreprise qui doivent se connecter à MaintainX.&lt;br&gt;Produire des documents clairs sur la portée de l&#39;intégration, des diagrammes de flux de données et des estimations d&#39;effort qui serviront de documents de transfert faisant autorité pour l&#39;équipe d&#39;après-vente.&lt;br&gt;Construire et maintenir une bibliothèque de modèles d&#39;intégration réutilisables, d&#39;actifs pré-construits et d&#39;architectures de référence pour accélérer les transactions futures.&lt;br&gt;Présenter la faisabilité et la complexité de l&#39;intégration lors des revues de transactions et des discussions sur la tarification, en signalant les risques de manière proactive à la direction des ventes.&lt;br&gt;Collaborez étroitement avec l&#39;équipe d&#39;intégration après-vente pour affiner les modèles de cadrage en fonction des réussites (et des échecs) lors de la mise en œuvre, et communiquez le pipeline à venir.&lt;br&gt;Réalisez des démonstrations en direct et des intégrations de validation de concept auprès des prospects lorsque cela est nécessaire.&lt;br&gt;Collaborez avec les équipes Produit, Ingénierie et Juridique pour défendre les besoins des prospects, accélérer le rythme des transactions et affiner le message de valeur.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;À propos de vous :&lt;/strong&gt;&lt;br&gt;Au moins 4 ans d&#39;expérience dans un poste en contact avec la clientèle, tel que l&#39;ingénierie de solutions, l&#39;avant-vente, le conseil technique ou un rôle similaire.&lt;br&gt;Connaissance approfondie des API REST, des webhooks, d&#39;OAuth et des modèles d&#39;intégration modernes.&lt;br&gt;Connaissance pratique approfondie des API, des flux de données et de l&#39;architecture des systèmes, acquise en collaborant avec des équipes d&#39;ingénierie et des parties prenantes commerciales.&lt;br&gt;Expérience avec les plateformes iPaaS (Workato, Boomi, MuleSoft, Zapier ou similaires).&lt;br&gt;Connaissance des modèles de prestation SaaS, y compris l’intégration, le déploiement après-vente et les processus de réussite client.&lt;br&gt;Expérience avec des systèmes d’entreprise tels que les systèmes ERP ou EAM (SAP, Oracle, IBM Maximo, Infor, etc.).&lt;br&gt;Capacité avérée à définir la portée des travaux techniques et à la traduire en estimations d’effort.&lt;/p&gt;
&lt;p&gt;&lt;br&gt;&lt;strong&gt;Ce que nous vous offrons :&lt;/strong&gt;&lt;br&gt;Un salaire compétitif et des opportunités d’actionnariat intéressantes.&lt;br&gt;Couverture santé, dentaire et optique.&lt;br&gt;Programme d&#39;adhésion au 401(k) / REER.&lt;br&gt;Prends les congés payés dont tu as besoin.&lt;br&gt;Une culture d&#39;entreprise où :&lt;br&gt;Tu travailleras aux côtés de collègues du monde entier qui incarnent les valeurs de MaintainX : « Smart Humble Optimist ».&lt;br&gt;Nous croyons en la méritocratie, où les idées et les efforts sont publiquement célébrés.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;À propos de nous :&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Notre mission est de fournir une plateforme unique aux équipes de maintenance, de réparation et d&#39;exploitation afin de maintenir le monde physique en état de fonctionnement. Nous croyons que le plus grand atout de toute organisation, ce sont les gens. C’est pourquoi nous avons conçu une solution intuitive et axée sur le mobile pour aider à stimuler la productivité et la collaboration entre les équipes et les sites.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;MaintainX s’engage à créer un environnement diversifié. Tous les candidats qualifiés seront pris en considération pour un emploi sans distinction de race, de couleur, de religion, de sexe, d’identité ou d’expression de genre, d’orientation sexuelle, d’origine nationale, de caractéristiques génétiques, de handicap, d’âge ou de statut d’ancien combattant.&amp;nbsp;&lt;/p&gt;

baincapitalventures-rent-the-runway:gree.descriptionHtml:
&lt;h4&gt;&lt;strong&gt;About Us:&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;Rent the Runway (RTR)&amp;nbsp; is transforming the way we get dressed by pioneering the world’s first Closet in the Cloud. Founded in 2009, RTR has disrupted the $2.4 trillion fashion industry by inspiring women with a more joyful, sustainable and financially-savvy way to feel their best every day. As the ultimate destination for circular fashion, the brand now offers infinite points of access to its shared closet via a fully customizable subscription to fashion, one-time rental or ownership. RTR offers designer apparel and accessories from hundreds of brand partners and has built in-house proprietary technology and a one-of-a-kind reverse logistics operation. RTR has been named to CNBC’s “Disruptor 50” five times in ten years, and has been placed on Fast Company’s Most Innovative Companies list multiple times.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;About the Job:&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;We are looking for a Senior Accountant to join our growing Finance team. The Senior Accountant will play a key role in the day-to-day operations of the Accounting group reporting directly to the Manager, Accounting. This is a great opportunity to be a part of a fast-paced, extremely successful, high energy company.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Support the month end close by preparing ongoing journal entries and accruals for revenue, expense and balance sheet accounts&lt;/li&gt;
&lt;li&gt;Maintain weekly and monthly schedules performing reconciliations of balance sheet accounts including, but not limited to fixed assets, prepaid expenses, other assets, accounts receivable and deferred liabilities&lt;/li&gt;
&lt;li&gt;Investigate reporting discrepancies / anomalies and communicate issues as they arise in a timely manner&lt;/li&gt;
&lt;li&gt;Review invoices, expense reports, and capital expenditures as needed to ensure proper coding and accounting treatment by Accounts Payable&lt;/li&gt;
&lt;li&gt;Assist in the preparation of support for the year-end financial statement audit, as well as any statutory audits that may arise&lt;/li&gt;
&lt;li&gt;Support the planning and budgeting team during the planning and budgeting processes by compiling ad-hoc reports and schedules&lt;/li&gt;
&lt;li&gt;Be a key collaborator for any company-wide system implementations&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About you&lt;/strong&gt;:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BA/BS degree in Accounting or Finance required&lt;/li&gt;
&lt;li&gt;4+ years of relevant accounting experience in either public accounting and/or relevant private industry experience&lt;/li&gt;
&lt;li&gt;CPA license preferred&lt;/li&gt;
&lt;li&gt;Must be a highly organized detail-oriented self-starter with the ability to work both independently and within a team environment&lt;/li&gt;
&lt;li&gt;Exceptional Excel skills - must be comfortable with analyzing and manipulating large data sets&lt;/li&gt;
&lt;li&gt;Ability to execute and follow-through on multiple tasks simultaneously&lt;/li&gt;
&lt;li&gt;Strong attention to detail&lt;/li&gt;
&lt;li&gt;Superior problem-solving skills&lt;/li&gt;
&lt;li&gt;Experience with a major ERP system preferred&lt;/li&gt;
&lt;li&gt;Strong work ethic and solutions oriented approach is a must&lt;/li&gt;
&lt;li&gt;Able and willing to communicate effectively with various internal and external partners at various levels&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Benefits:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Rent the Runway, we’re committed to the wellbeing of our employees, and aim to create a workplace that fosters both personal and professional growth. Our inclusive benefits include, but are not limited to:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Paid Time Off including vacation, paid bereavement, and family sick leave - every employee needs time to take care of themselves and their family.&lt;/li&gt;
&lt;li&gt;Universal Paid Parental Leave for both parents + flexible return to work program&amp;nbsp; - because we know your newest family member(s) deserve your undivided attention.&lt;/li&gt;
&lt;li&gt;Paid Sabbatical after 5 years of continuous service - Unplug, recharge, and have some fun!&lt;/li&gt;
&lt;li&gt;Exclusive employee subscription and rental discounts -&amp;nbsp; to ensure you experience the magic of renting the runway (and give us valued feedback!).&lt;/li&gt;
&lt;li&gt;Comprehensive health, vision, dental, FSA and dependent care from day 1 of employment - Your health comes first and we’ve got you covered.&lt;/li&gt;
&lt;li&gt;401k match - an investment in your future.&lt;/li&gt;
&lt;li&gt;Company wide events and outings - our team spirit is no joke - we know how to have fun!&lt;/li&gt;
&lt;li&gt;Hybrid work - our accounting team have the option to work remotely two days per week, in accordance with Company policies.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;em&gt;Rent the Runway is an equal opportunity employer. In accordance with applicable law, we prohibit discrimination against any applicant or employee based on any legally-recognized basis, including, but not limited to: race, color, religion, sex (including pregnancy, lactation, childbirth or related medical conditions), sexual orientation, gender identity, age (40 and over), national origin or ancestry, citizenship status, physical or mental disability, genetic information (including testing and characteristics), veteran status, uniformed service member status or any other status protected by federal, state or local law.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;_________&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;The anticipated base salary for this position is $85,000 to $105,000. The actual base salary offered will depend on a variety of factors, including without limitation, the qualifications of the individual applicant for the position, years of relevant experience, level of education attained, certifications or other professional licenses held.&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;By submitting your application below, you agree that you have read and acknowledge Rent the Runway&#39;s Candidate Privacy Policy, found &lt;a href=&quot;https://www.renttherunway.com/privacy#candidate-privacy-notice&quot;&gt;here&lt;/a&gt;.&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

