&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in profiling / optimising high performance code.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience of writing ML kernels.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience of using and/or development of ML Frameworks.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in a computationally intensive engineering field.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;In addition to a competitive salary, Graphcore offers flexible working, a generous annual leave policy, private medical insurance and health cash plan, a dental plan, pension (matched up to 5%), life assurance and income protection. We have a generous parental leave policy and an employee assistance programme (which includes health, mental wellbeing, and bereavement support). We offer a range of healthy food and snacks at our central Bristol office and have our own barista bar! We welcome people of different backgrounds and experiences; we’re committed to building an inclusive work environment that makes Graphcore a great home for everyone. We offer an equal opportunity process and understand that there are visible and invisible differences in all of us. We can provide a flexible approach to interview and encourage you to chat to us if you require any reasonable adjustments.&lt;/p&gt;
&lt;p&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Applicants for this position must hold the right to work in the UK. Unfortunately at this time, we are unable to provide visa sponsorship or support for visa applications&lt;/em&gt;&lt;/p&gt;

balderton-graphcore:greenhouse:856375500.descriptionHtml:
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Salary Range: PLN 350,700 - 474,400 + Benefits + Equity&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Subject to alignment to the responsibilities and duties of the role.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: medium;&quot;&gt;Location: Gdańsk - Hybrid Working Policy - 2-3 Days per week in office&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;About Graphcore&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;At Graphcore, we’re building the future of AI compute.We’re a team of semiconductor, software and AI experts, with deep experience in creating the complete AI compute stack - from silicon and software to infrastructure at datacenter scale.As part of the SoftBank Group, backed by significant long-term investment, we are delivering key technology into the fast-growing SoftBank AI ecosystem.To meet the vast and exciting AI opportunity, Graphcore is expanding its teams around the world.We are bringing together the brightest minds to solve the toughest problems, in a place where everyone has the opportunity to make an impact on the company, our products and the future of artificial intelligence.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Job Summary&amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;You will contribute to the architecture, implementation and deployment of highly scalable management and observability solutions for AI infrastructure built using our next-generation products.&amp;nbsp;&amp;nbsp;Covering monitoring, observability, control, and data center infrastructure management, you will work with software, cloud and customer-facing teams, to establish first-hand knowledge of these solutions, creating proof-of-concepts, reference designs and integrations with third-party tooling.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Your team will work with product, architecture and other delivery teams to ensure that functionally complete, simple to deploy, and easy to use solutions are deployed internally to support engineering efforts and supply reference designs to our customers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Responsibilities and Duties&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Contribute to all phases of overall product development, from product definition, architecture, and design, through implementation, debugging, testing and early customer support.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Contribute to the design and implementation of fault-remediation solutions at scale.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Implement multi-component integrations based on Graphcore and third-party technology stacks, from data ingestion to decision making, ensuring seamless management, monitoring and UI.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Create reference designs including documentation, configuration files, scripts, source code, etc.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Deploy solution(s) internally for use by our engineering teams to aid debugging, performance analysis, benchmarking, test/QA, etc. at all scales.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Maintain and improve deployed infrastructure long term to provide the best service for our customers.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Ensure solutions are properly tested by working with the development and QA teams to enhance unit testing&amp;nbsp;and ensure a&amp;nbsp;comprehensive test plan is in place.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Mentor and guide junior engineers, fostering a culture of continuous learning and improvement.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Skills and Experience&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;BSc or MSc degree in Computer Engineering, Computer Science, or related degree or equivalent experience.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Demonstrated success in&amp;nbsp;architecting and implementing scalable,&amp;nbsp;performant, reliable&amp;nbsp;cluster management systems including telemetry collection &amp;amp; analysis engines.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience in managing big scale datacenters focusing on hardware observability solutions.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience in maintaining and scaling modern observability stacks using Prometheus, Grafana, OTEL, ClickHouse, Kafka, Superset or Elastic Stack&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Understanding of secure telemetry practices and data exposure controls.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Working knowledge of Datadog, Dynatrace or Splunk.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience in large-scale telemetry datasets, time series databases, down-sampling techniques, and creating actionable dashboards.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience&amp;nbsp;automation technologies, such as Ansible or Terraform.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience in containerisation (Docker, Kubernetes)&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Experience in managing or developing in Linux environments.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Strong and demonstrable skill in at least one of C/C++/Go and Python.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Excellent written and verbal communication skills.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Desirable:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Knowledge of cloud-native development and deployment methodologies (SaaS/PaaS/IaaS).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Knowledge of data center networking and monitoring best practices.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Knowledge of monitoring, observability and management solutions in use by hyperscalers.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Knowledge of declarative management systems.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2 style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;In addition to a competitive salary, annual leave policy, medical and dental health plans, a gym card and employee pension (matched up to 4%). We review our benefits on a yearly basis to ensure we offer a valuable and rewarding benefits programme to our employees. &amp;nbsp;We welcome people of different backgrounds and experiences; we’re committed to building an inclusive work environment that makes Graphcore a great home for everyone. We offer an equal opportunity process and understand that there are visible and invisible differences in all of us. We can provide a flexible approach to interview and encourage you to chat to us if you require any reasonable adjustments.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h2 style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Sponsorship&lt;/strong&gt;&lt;/span&gt;&lt;/h2&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;Applicants for this position must hold the right to work in the Poland. Unfortunately at this time, we are unable to provide visa sponsorship or support for visa applications.&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

balderton-wayve:greenhouse:8501381002.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h2&gt;&lt;strong&gt;About us&amp;nbsp;&lt;/strong&gt;&amp;nbsp;&amp;nbsp;&lt;/h2&gt;
&lt;p&gt;Founded in 2017, Wayve is the leading developer of Embodied AI technology.&amp;nbsp; Our advanced AI software and foundation models enable vehicles to perceive, understand, and navigate any complex environment, enhancing the usability and safety of automated driving systems.&lt;/p&gt;
&lt;p&gt;Our vision is to create autonomy that propels the world forward.&amp;nbsp; Our intelligent, mapless, and hardware-agnostic AI products are designed for automakers, accelerating the transition from assisted to automated driving.&amp;nbsp; &lt;br&gt;&lt;br&gt;In our fast-paced environment big problems ignite us—we embrace uncertainty, leaning into complex challenges to unlock groundbreaking solutions. We aim high and stay humble in our pursuit of excellence, constantly learning and evolving as we pave the way for a smarter, safer future.&lt;/p&gt;
&lt;p&gt;At Wayve, your contributions matter.&amp;nbsp; We value diversity, embrace new perspectives, and foster an inclusive work environment; we back each other to deliver impact.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Make Wayve the experience that defines your career!&amp;nbsp;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;h2&gt;&lt;strong&gt;The Role&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;In this role, you will play a critical part in supporting our customers throughout the entire development lifecycle, from the initial integration phase to the final validation of our technology. You will ensure that customers receive responsive, high-quality technical support and work closely with both our clients and internal engineering teams to ensure seamless integration of our technology into their vehicles.&lt;/p&gt;
&lt;p&gt;Located near our customers, you will be in a prime position to perform rapid diagnostics, identify issues in real time, and collaborate directly with customer engineering teams. This proximity allows you to maintain a holistic understanding of the system and effectively distinguish between vehicle-related issues and those specific to the Wayve AI Driver.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Key Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Provide hands-on technical support to customers throughout the development and validation process&lt;/li&gt;
&lt;li&gt;Serve as the bridge between customer vehicle integration teams and Wayve’s internal engineering teams&lt;/li&gt;
&lt;li&gt;Troubleshoot and resolve technical issues related to our technology independently&lt;/li&gt;
&lt;li&gt;Escalate complex or critical issues to the appropriate internal stakeholders&lt;/li&gt;
&lt;li&gt;Develop deep understanding of customer systems and APIs (e.g. drive-by-wire) to effectively guide internal teams&lt;/li&gt;
&lt;li&gt;Maintain a system-level perspective to identify root causes, whether vehicle-based or software-related&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;About you&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;In order to set you up for success as a Customer Integration Engineer at Wayve, we’re looking for the following skills and experience.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong problem-solving skills and analytical thinking&lt;/li&gt;
&lt;li&gt;Proven ability to lead investigations into platform or vehicle issues in collaboration with internal and customer teams&lt;br&gt;Extensive hands-on experience with development vehicles&lt;/li&gt;
&lt;li&gt;Proficiency with diagnostic and calibration tools (e.g. CANape or similar)&lt;/li&gt;
&lt;li&gt;Familiarity with terminal usage and a willingness to develop basic programming skills&lt;/li&gt;
&lt;li&gt;Solid understanding of vehicle communication protocols (e.g. CAN, Ethernet) and automotive system architectures&lt;/li&gt;
&lt;li&gt;Practical experience working in an automotive environment, ideally with a track record of bringing products to production&lt;/li&gt;
&lt;li&gt;Excellent communication and interpersonal skills for effective collaboration with both customers and internal teams&lt;/li&gt;
&lt;li&gt;Willingness to travel as required&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;This role is a full-time role based in Sunnyvale or Detroit (hybrid) and the reasonably estimated salary for this role ranges from $137,300 to $187,000, plus a competitive equity package. Actual compensation is based on the candidate&#39;s skills, qualifications, and experience.&lt;/p&gt;
&lt;p&gt;At Wayve we want the best of all worlds so we operate a hybrid working policy that combines time together in our offices and workshops to fuel innovation, culture, relationships and learning, and time spent working from home. We operate core working hours so you can determine the schedule that works best for you and your team.&amp;nbsp;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;#LI-KM1&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span class=&quot;notion-enable-hover&quot; data-token-index=&quot;0&quot;&gt;Wayve is committed to creating an inclusive interview experience. If you require any accommodations or adjustments to participate fully in our interview process, please let us know.&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;We understand that everyone has a unique set of skills and experiences and that not everyone will meet all of the requirements listed above. If you’re passionate about self-driving cars and think you have what it takes to make a positive impact on the world, we encourage you to apply.&lt;br&gt;&lt;br&gt;At Wayve we&#39;re committed to creating a diverse, fair and respectful culture that is inclusive of everyone based on their unique skills and perspectives, and regardless of sex, race, religion or belief, ethnic or national origin, disability, age, citizenship, marital, domestic or civil partnership status, sexual orientation, gender identity, veteran status, pregnancy or related condition&amp;nbsp; (including breastfeeding) or any other basis as protected by applicable law. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;For more information visit &lt;a href=&quot;https://wayve.ai/careers/&quot;&gt;Careers at Wayve.&amp;nbsp;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;To learn more about what drives us, visit &lt;a href=&quot;https://wayve.ai/careers/&quot;&gt;Values at Wayve&amp;nbsp;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;For US candidates only, please visit &lt;a href=&quot;https://www.e-verify.gov/sites/default/files/everify/posters/EVerifyParticipationPoster.pdf&quot;&gt;E-Verify Notice&lt;/a&gt; and &lt;a href=&quot;https://www.ussc.gov/sites/default/files/pdf/employment/RightToWork.pdf&quot;&gt;Participation and Right to Work&lt;/a&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;DISCLAIMER: We will not ask about marriage or pregnancy, care responsibilities or disabilities in any of our job adverts or interviews. However, we do look to capture information about care responsibilities, and disabilities among other diversity information as part of an optional DEI Monitoring form to help us identify areas of improvement in our hiring process and ensure that the process is inclusive and non-discriminatory.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

battery-gong:greenhouse:4674640006.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Gong harnesses the power of AI to transform how revenue teams win. The Gong Revenue AI Operating System unifies data, insights, and workflows into a single, trusted system that observes, guides, and acts alongside the world’s most successful revenue teams. Powered by the Gong Revenue Graph, AI-powered intelligence, specialized agents, and trusted applications, Gong helps more than 5,000 companies around the world deeply understand their teams and customers, automate critical sales workflows, and close more deals with less effort. For more information, visit www.gong.io.&lt;/p&gt;
&lt;p&gt;At Gong, you will join a company built on innovative products, ambitious goals, and passionate people. We are shaping the future of revenue intelligence and we want people who are excited to build what comes next. You will work with a team that dreams big, moves fast, and cares deeply about the craft and about each other. Here, transparency and trust are core to how we operate, and every person has the opportunity to make a visible impact. If you want to grow, stretch, and do work that truly matters, Gong is the place to do the best work of your career.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;This is a high-impact, Senior Manager-level individual contributor role for someone who thrives in a fast-paced SaaS environment and wants to help build a best-in-class legal function aligned to a high-velocity go-to-market engine. This role is designed to evolve, with the opportunity to take on people leadership as the team scales.&lt;/p&gt;
&lt;h5&gt;RESPONSIBILITIES&lt;/h5&gt;
&lt;p&gt;&lt;span class=&quot;im&quot;&gt;Lead negotiation and structuring of complex, high-value enterprise SaaS agreements with strategic customers&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partner closely with Sales leadership and executive stakeholders to enable revenue growth and shape deal strategy&lt;/li&gt;
&lt;li&gt;Provide clear, business-oriented legal guidance that appropriately balances risk with commercial outcomes&lt;/li&gt;
&lt;li&gt;Act as a senior resource and mentor to commercial lawyers, contributing to the development of team capabilities and standards&lt;/li&gt;
&lt;li&gt;Help identify opportunities to strengthen the team over time, including contributing to hiring, onboarding, and development efforts as the function grows&lt;/li&gt;
&lt;li&gt;Drive the development and scaling of legal processes, templates, and playbooks to support a rapidly growing Sales organization&lt;/li&gt;
&lt;li&gt;Serve as a senior escalation point for complex deal issues and cross-functional challenges&lt;/li&gt;
&lt;li&gt;Collaborate cross-functionally with Product, Security, Privacy, and Finance to support evolving business needs&lt;/li&gt;
&lt;li&gt;Help shape Legal’s operating model and team structure as the company scales into its next stage of growth&lt;/li&gt;
&lt;/ul&gt;
&lt;h5&gt;QUALIFICATIONS&amp;nbsp;&lt;/h5&gt;
&lt;div&gt;* JD and active bar membership in at least one U.S. state&lt;/div&gt;
&lt;div&gt;* 6–10+ years of experience in commercial transactions, including meaningful in-house experience at a SaaS or technology company&lt;/div&gt;
&lt;div&gt;* Strong experience negotiating complex enterprise SaaS agreements with large customers&lt;/div&gt;
&lt;div&gt;* Demonstrated ability to operate independently and exercise sound legal and business judgment in high-stakes situations&lt;/div&gt;
&lt;div&gt;* Experience mentoring or leading other attorneys, formally or informally&lt;/div&gt;
&lt;div&gt;* Ability to communicate complex legal concepts clearly and effectively to business stakeholders&lt;/div&gt;
&lt;div&gt;* Comfort operating in a high-growth, fast-paced environment with evolving priorities&lt;/div&gt;
&lt;h5&gt;PREFERRED QUALIFICATIONS&lt;/h5&gt;
&lt;div&gt;* Experience supporting high-growth SaaS companies at scale&lt;/div&gt;
&lt;div&gt;* Familiarity with enterprise sales processes and go-to-market dynamics&lt;/div&gt;
&lt;div&gt;* Experience building or improving legal processes (CLM, playbooks, templates)&lt;/div&gt;
&lt;div&gt;* Track record of partnering effectively with executive leadership&lt;/div&gt;
&lt;div&gt;* Experience serving as a primary legal partner to enterprise sales teams in a SaaS environment, with ownership of large, strategic deals&lt;/div&gt;
&lt;h5&gt;PERKS &amp;amp; BENEFITS&amp;nbsp;&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;We offer Gongsters a variety of medical, dental, and vision plans, designed to fit you and your family’s needs.&lt;/li&gt;
&lt;li&gt;Wellbeing Fund - flexible wellness stipend to support a healthy lifestyle.&lt;/li&gt;
&lt;li&gt;Mental Health benefits with covered therapy and coaching.&lt;/li&gt;
&lt;li&gt;401(k) program to help you invest in your future.&lt;/li&gt;
&lt;li&gt;Education &amp;amp; learning stipend for personal growth and development.&lt;/li&gt;
&lt;li&gt;Flexible vacation time to promote a healthy work-life blend.&lt;/li&gt;
&lt;li&gt;Paid parental leave to support you and your family.&lt;/li&gt;
&lt;li&gt;Company-wide recharge days each quarter.&lt;/li&gt;
&lt;li&gt;Work from home stipend to help you succeed in a remote environment.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;The annual salary hiring range for this position is $220,000 - $260,000 USD.&amp;nbsp; &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Compensation is based on factors unique to each candidate, including, but not limited to, job-related skills, qualification, education, experience, and location. At Gong, we have a location-based compensation structure, which means there may be a different range for candidates in other locations. The total compensation package for this position, in addition to base compensation, may include incentive compensation, bonus, equity, and benefits. Some of our sales compensation programs also offer the potential to achieve above targeted earnings for those who exceed their sales targets.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are always looking for outstanding Gongsters! So if this sounds like something that interests you regardless of compensation, please reach out. We may have more roles for you to consider and would love to connect.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We have noticed a rise in recruiting impersonations across the industry, where scammers attempt to access candidates&#39; personal and financial information through fake interviews and offers. All Gong recruiting email communications will always come from the @gong.io domain. Any outreach claiming to be from Gong via other sources should be ignored.&lt;/strong&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&lt;em&gt;Gong is an equal-opportunity employer. We believe that diversity is integral to our success, and do not discriminate based on race, color, religion, age, sex, sexual orientation, gender identity, national origin, disability, military status, genetic information, or any other basis protected by applicable law.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;To review Gong&#39;s privacy policy, visit &lt;a href=&quot;https://www.gong.io/gong-io-job-candidates-privacy-notice/&quot; target=&quot;_blank&quot;&gt;https://www.gong.io/gong-io-job-candidates-privacy-notice/&lt;/a&gt; for more details.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;#LI-NK1&lt;/em&gt;&lt;/p&gt;

battery-kodiak-robotics:greenhouse:42948.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Kodiak Robotics, Inc. was founded in 2018 and has become a leader in autonomous ground transportation committed to a safer and more efficient future for all. The company has developed an artificial intelligence (AI) powered technology stack purpose-built for commercial trucking and the public sector. The company delivers freight daily for its customers across the southern United States using its autonomous technology. In 2024, Kodiak became the first known company to publicly announce delivering a driverless semi-truck to a customer. Kodiak is also leveraging its commercial self-driving software to develop, test and deploy autonomous capabilities for the U.S. Department of Defense.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;We are looking for a Staff Software Engineer to help shape how learned models are integrated into behavior planning for autonomous driving. In this role, you will sit at the intersection of Planning and Machine Learning, working closely with ML engineers and autonomy teams to bring learned components into a production autonomy stack.&lt;/p&gt;
&lt;p&gt;This is a high-impact role for someone who understands both the practical constraints of real-world planning systems and the opportunities enabled by modern learned models. You will help shape how ML improves autonomy behavior while ensuring that new capabilities are safe, measurable, debuggable, and deployable.&lt;/p&gt;
&lt;h4&gt;What You’ll Do&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Lead Planning-side integration of learned models into the behavior planning stack.&lt;/li&gt;
&lt;li&gt;Collaborate closely with ML teams on model improvements, requirements, evaluation, and deployment.&lt;/li&gt;
&lt;li&gt;Work on learned planning components as well as other ML-driven planning signals, such as behavior classification, actor intent understanding, and data-driven decision-making.&lt;/li&gt;
&lt;li&gt;Design integration strategies that balance learned components with existing heuristic planning systems.&lt;/li&gt;
&lt;li&gt;Define validation, fallback, monitoring, and safety criteria for learned planning components.&lt;/li&gt;
&lt;li&gt;Debug and analyze model behavior using simulation, logs, metrics, and real-world autonomy data.&lt;/li&gt;
&lt;li&gt;Partner with cross-functional teams across Perception, ML, Planning, Simulation, Systems, and Safety.&lt;/li&gt;
&lt;li&gt;Lead technical designs and mentor other engineers.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;What We’re Looking For&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Strong experience in autonomous vehicles, robotics, or a related autonomy domain.&lt;/li&gt;
&lt;li&gt;Deep technical background in behavior planning, decision-making, or motion planning.&lt;/li&gt;
&lt;li&gt;Strong software engineering skills with proficiency in C++. Python proficiency is a plus.&lt;/li&gt;
&lt;li&gt;Experience working with heuristic or classical planning systems.&lt;/li&gt;
&lt;li&gt;Experience integrating or developing learned behavior policies, behavior classification, trajectory prediction, or actor intent models.&lt;/li&gt;
&lt;li&gt;Ability to reason about safety, system behavior, evaluation, and deployment risk.&lt;/li&gt;
&lt;li&gt;Excellent cross-functional communication and technical leadership skills.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The pay range listed below reflects the base salary&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;in our SF/Silicon Valley location,&amp;nbsp;&lt;/strong&gt;across several internal levels. Actual starting pay will be based on job-related factors including: work location, experience, relevant training, education, skill level and performance during interview. Total compensation at Kodiak includes base pay, equity, bonus and a competitive benefits package&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;California Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$240,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$265,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;At Kodiak, we strive to build a diverse community working towards our common company goals in a safe and collaborative environment where harassment of any kind is strictly prohibited. Kodiak is committed to equal opportunity employment regardless of race, ethnicity, religion, gender identity, sexual orientation, age, disability, or veteran status, or any other basis protected by applicable law.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;In alignment with its business operations, Kodiak adheres to all relevant statutes, regulations, and administrative prerequisites. Accordingly, roles that carry more sensitive requirements may be limited to candidates that can satisfy additional scrutiny and eligibility for such positions may hinge on verification of a candidate’s residence, U.S. person status, and/or citizenship status. Should the position require, and Kodiak determines that a candidate’s residence, U.S. person status, and/or citizenship status necessitate an export license, bar the candidate from the position, or otherwise fall under national security-related restrictions, Kodiak will consider the candidate for alternative positions unaffected by such restrictions, under terms and conditions set forth at Kodiak’s sole discretion, or, as an alternative, opt not to proceed with the candidate’s application. If applicable, Kodiak may provide visa sponsorship for eligible candidates.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;We use a third-party AI tool (Endorsed) to assist in the initial screening of applications. As part of the evaluation process, we provide Endorsed with job requirements and candidate-submitted applications. Final hiring decisions are made by our human recruitment team, and no automated system makes the ultimate decision regarding hiring. Certain features of the platform may qualify it as an Automated Employment Decision Tool (AEDT) under applicable regulations. We began using Endorsed on January 1, 2026. You can review the independent bias audit report covering our use of Endorsed [here](&lt;/em&gt;&lt;em&gt;&lt;a href=&quot;https://endorsed.com/local-law-144&quot; target=&quot;_blank&quot; data-sk=&quot;tooltip_parent&quot;&gt;https://endorsed.com/local-law-144&lt;/a&gt;&lt;/em&gt;&lt;em&gt;). By submitting your application, you acknowledge that your application may be processed by AI systems as part of the screening and selection process. If you have any questions or would like to request a separate review of your application, please contact &lt;/em&gt;&lt;em&gt;&lt;a href=&quot;mailto:careers@kodiak.ai&quot; target=&quot;_blank&quot; data-sk=&quot;tooltip_parent&quot;&gt;careers@kodiak.ai&lt;/a&gt;&lt;/em&gt;&lt;em&gt; with &quot;Separate Review Request&quot; in the email subject line.&lt;/em&gt;&lt;/div&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;

battery-mattermost:greenhouse:5169029008.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;div&gt;Mattermost is the leading collaborative workflow platform for defense, intelligence, security, and critical infrastructure. Trusted by the U.S. Department of War and Fortune 500s, our platform runs on-premises and in private clouds, delivering secure messaging, file sharing, workflow automation, audio/screenshare, and project management—all with full data and operational control. Mattermost powers high-stakes workflows across mission planning, real-time, real-world operations, DevSecOps, incident response, and cyber defense—enabling secure collaboration from tactical edge and DDIL environments to enterprise HQ. Teams operate across web, desktop, and mobile, with embedded interoperability for Microsoft Teams, Outlook, and Microsoft 365.&lt;br&gt;&lt;br&gt;&lt;/div&gt;
&lt;div&gt;To learn more, visit&amp;nbsp;&lt;a href=&quot;http://www.mattermost.com/&quot;&gt;www.mattermost.com&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;&lt;p&gt;Mattermost is seeking&amp;nbsp;a fully remote &lt;strong&gt;US Defense Software Engineering Lead&lt;/strong&gt; anywhere in the United States&amp;nbsp;to lead a small, agile development team dedicated to building mission-critical capabilities on top of the Mattermost platform for US national security customers. You will sit at the intersection of product delivery, customer partnership, and engineering excellence — translating the complex operational needs of defense users into software that works reliably in the most demanding environments on earth.&lt;/p&gt;
&lt;p&gt;This is not a role for a detached manager. You will be hands-on, customer-facing, and deeply invested in the US national security mission. You&#39;ll collaborate closely with customers and forward-deployed engineers to gather requirements from the field, then translate those requirements back to your product engineering team to drive delivery. You will own the full stack — from architecture decisions to shipping — and set the bar for quality, velocity, and accountability.&lt;/p&gt;
&lt;p&gt;Do you thrive in high-stakes environments where the software you build genuinely matters? Are you energized by leading focused, high caliber engineers and working directly alongside the customers who depend on your work? Do you embrace AI as a force-multiplier for engineering productivity? If so, we want to hear from you.&lt;/p&gt;
&lt;h2&gt;What You&#39;ll Do&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Work remotely and autonomously within a distributed, global team — you&#39;ll own your work and stay closely connected across time zones.&lt;/li&gt;
&lt;li&gt;Lead, mentor, and grow a small, agile full-stack engineering team focused on delivering product capabilities tailored to US national security customers on top of the Mattermost platform.&lt;/li&gt;
&lt;li&gt;Own the end-to-end engineering delivery lifecycle: requirements, architecture, development, testing, and release.&lt;/li&gt;
&lt;li&gt;Collaborate with customers and forward-deployed engineers to capture requirements directly from the field and translate them into well-scoped, executable engineering work for the core team.&lt;/li&gt;
&lt;li&gt;Interface directly and professionally with US national security customers — building trust, managing expectations, and communicating technical trade-offs clearly to non-engineers.&lt;/li&gt;
&lt;li&gt;Partner with product and design stakeholders to define roadmaps that balance customer needs, platform constraints, and strategic priorities.&lt;/li&gt;
&lt;li&gt;Maintain a full-stack technical perspective, contributing to architecture decisions across frontend, backend, and infrastructure layers.&lt;/li&gt;
&lt;li&gt;Establish and uphold engineering standards for code quality, security, testing, and documentation appropriate for a defense-grade software environment.&lt;/li&gt;
&lt;li&gt;Champion the adoption of AI-powered development tools (e.g., Cursor, Claude, GitHub Copilot) across the team to accelerate velocity and automate repetitive engineering tasks.&lt;/li&gt;
&lt;li&gt;Actively manage team health: conduct regular 1:1s, identify growth opportunities, address blockers, and foster a culture of ownership and psychological safety.&lt;/li&gt;
&lt;li&gt;Participate in technical hiring and onboarding to expand the team as the mission scales.&lt;/li&gt;
&lt;li&gt;Provide accurate effort estimates, status updates, and risk assessments to leadership and program stakeholders on a regular cadence.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;What We&#39;re Looking For&lt;/h2&gt;
&lt;h3&gt;Required Qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;BS in Computer Science, Computer Engineering, or related field/experience.&lt;/li&gt;
&lt;li&gt;5+ years of professional software engineering experience, including 2+ years in an engineering management or tech lead role.&lt;/li&gt;
&lt;li&gt;Proven full-stack product development experience — comfortable owning decisions across frontend (e.g., React) and backend (e.g., Go, Node.js) layers.&lt;/li&gt;
&lt;li&gt;Demonstrated ability to lead small, agile teams in a fast-paced, high-accountability environment.&lt;/li&gt;
&lt;li&gt;Experience interfacing directly with customers or end users in a technical capacity — able to listen, synthesize, and communicate complex technical concepts clearly to non-engineers.&lt;/li&gt;
&lt;li&gt;Strong written and verbal communication skills for collaborating across distributed, remote teams and presenting to senior stakeholders.&lt;/li&gt;
&lt;li&gt;Proficiency with AI/LLM development tools (e.g., Cursor, GitHub Copilot, Claude) with a genuine commitment to integrating them into daily engineering workflows.&lt;/li&gt;
&lt;li&gt;US citizenship is required. This role may require the ability to obtain and maintain a US government security clearance in the future. Applicants must reside in the United States.&lt;/li&gt;
&lt;li&gt;Applicants must meet eligibility requirements for access to export-controlled information as defined by US export control laws, including EAR and ITAR.&lt;/li&gt;
&lt;li&gt;Strong personal alignment with the US national security mission and the communities it serves.&lt;/li&gt;
&lt;li&gt;Travel 1-2 weeks per quarter.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Clearance Requirements&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Must be eligible to obtain and maintain a U.S. security clearance&lt;/li&gt;
&lt;li&gt;Active Secret clearance preferred; TS/SCI is a plus&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred Qualifications&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Previous experience working with or for the US Department of Defense (DoD), defense contractors, or the intelligence community.&lt;/li&gt;
&lt;li&gt;Familiarity with defense-specific software environments, including DDIL (Disconnected, Denied, Disrupted, Intermittent, and Limited) network conditions.&lt;/li&gt;
&lt;li&gt;Experience working fully remotely with distributed, global teams.&lt;/li&gt;
&lt;li&gt;Background building secure, compliant software for government or regulated industries.&lt;/li&gt;
&lt;li&gt;Experience hiring, growing, and retaining exceptional engineering talent in a remote environment.&lt;/li&gt;
&lt;li&gt;Prior work in open-source projects or platform-level software development.&lt;/li&gt;
&lt;li&gt;Contributions to Mattermost or similar collaboration/communications platforms.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Why Mattermost&lt;/h2&gt;
&lt;p style=&quot;padding-left: 40px;&quot;&gt;Mattermost is uniquely positioned at the intersection of secure collaboration, mission software, and defense modernization. This role offers the opportunity to shape and scale Mattermost&#39;s presence within one of the largest and most strategic branches of the U.S. Department of Defense.&lt;/p&gt;
&lt;p style=&quot;padding-left: 40px;&quot;&gt;If you thrive in complex environments, understand how mission outcomes drive technology adoption, and want to sell software that matters—we&#39;d love to hear from you.&lt;/p&gt;
&lt;h3 class=&quot;font-claude-response-body break-words whitespace-normal leading-[1.7]&quot;&gt;Compensation&lt;/h3&gt;
&lt;p class=&quot;font-claude-response-body break-words whitespace-normal leading-[1.7]&quot;&gt;&lt;em&gt;Mattermost takes a market-based approach to pay and pay may vary depending on your location. The successful candidate&#39;s starting pay will be determined based on job-related skills, experience, qualifications, work location, and market conditions. These ranges may be modified in the future.&lt;/em&gt;&lt;/p&gt;
&lt;p class=&quot;font-claude-response-body break-words whitespace-normal leading-[1.7]&quot;&gt;&lt;strong&gt;Base Salary Range: $180,000 – $245,000 USD&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;Mattermost is an EEO Employer, we are a remote-first, open-source company.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We are continually working to expand our hiring in more countries and regions, ensuring compliance with local laws and regulations, which takes time.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Mattermost values your unique perspective—we welcome all applicants. We encourage individuals from all backgrounds to apply and are committed to assessing candidates based on their skills and qualifications. We do not tolerate discrimination against staff or applicants based on race, religion, national origin, age, disability, pregnancy status, veteran status, or other personal characteristics.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;If you require accommodations during the interview process, please let us know—we’re happy to assist.&lt;/div&gt;&lt;/div&gt;

battery-n26:greenhouse:8023346.descriptionHtml:
&lt;h2&gt;About the opportunity&lt;/h2&gt;
&lt;p&gt;N26 is looking for a Risk Associate to support the further development of the risk controlling function at a cutting-edge technology-driven bank. In this role, you will have the opportunity to learn and contribute to assessing, controlling, and reporting N26&#39;s risks.&lt;/p&gt;
&lt;h2&gt;In this role you will:&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Support senior colleagues in establishing risk management and control tools.&lt;/li&gt;
&lt;li&gt;Assist in the implementation and adherence to regulatory requirements for risk controlling (e.g., MaRisk, ICAAP guidelines, EBA guidelines, MaSan, SAG).&lt;/li&gt;
&lt;li&gt;Contribute to running and improving the risk management and risk controlling of the N26 group (including recovery plan, RWA calculation, risk appetite, risk policies and decision-making frameworks, limit setting and monitoring, internal controls).&lt;/li&gt;
&lt;li&gt;Support performing and further developing risk inventory according to new business areas and the incorporation of ESG risks.&lt;/li&gt;
&lt;li&gt;Support capital planning and the derivation of relevant stress tests and their parameters.&lt;/li&gt;
&lt;li&gt;Further develop risk reporting at N26 group and continuously contribute to generating insights to support steering in accordance with the risk and business strategies.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;What you need to be successful:&lt;/h2&gt;
&lt;p&gt;Background &amp;amp; Skills&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Master’s degree in business/economics or similar&lt;/li&gt;
&lt;li&gt;First professional experience from internships in financial services and risk management&lt;/li&gt;
&lt;li&gt;Eagerness to learn about regulatory requirements (e.g.,&amp;nbsp; MaRisk, CRR, ICAAP guidelines, MaSan, SAG)&lt;/li&gt;
&lt;li&gt;Experience in risk reporting and solid understanding of the overall ICAAP and relevant methods (e.g., risk bearing capacity, risk inventory, capital planning, recovery plan) is a strong plus&lt;/li&gt;
&lt;li&gt;Detail oriented and reliable with a professional attitude, as you will contribute to sensitive risk controlling topics on which management decisions are made&lt;/li&gt;
&lt;li&gt;Strong analytical, organizational skills with ability to meet tight time schedules&lt;/li&gt;
&lt;li&gt;Ability to recognize and resolve problems, identify issues and proactively work towards resolution&lt;/li&gt;
&lt;li&gt;Excellent proficiency in Excel and/or Google Sheets, including the ability to work with complex datasets and create insightful reports.&lt;/li&gt;
&lt;li&gt;Excellent English communication skills, both verbal and written, are essential. Given the German regulatory environment, German language skills are a strong plus.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Traits:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Strong ownership and a proactive attitude.&lt;/li&gt;
&lt;li&gt;Curiosity and a drive to continuously learn and improve.&lt;/li&gt;
&lt;li&gt;Passion for data and problem-solving.&lt;/li&gt;
&lt;li&gt;Flexibility and adaptability in a fast-changing environment.&lt;/li&gt;
&lt;li&gt;Team player with a willingness to actively support colleagues.&lt;/li&gt;
&lt;li&gt;Openness to direct feedback.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;What’s in it for you:&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Accelerate your career growth by joining one of Europe’s most talked about disruptors 🚀.&lt;/li&gt;
&lt;li&gt;Employee benefits that range from a competitive personal development budget, work from home budget, discounts to fitness &amp;amp; wellness memberships, language apps and public transportation.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;As an N26 employee you will have access to a Premium subscription on your personal N26 bank account. As well as subscriptions for friends and family members.&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Additional day of annual leave for each year of service.&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A high degree of autonomy and access to cutting edge technologies - all while working with a friendly team of peers of diverse nationalities, life experiences and family statuses.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A relocation package with visa support for those who need it.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&amp;nbsp;&lt;/h2&gt;
&lt;h2&gt;&lt;strong&gt;Who we are&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;N26 has reimagined banking for today’s digital world. Technology and design empower&lt;a href=&quot;https://n26.com/en-eu/blog&quot;&gt; everything we do&lt;/a&gt; and it’s how we are building the global banking platform the world loves to use.&lt;/p&gt;
&lt;p&gt;We&#39;ve eliminated physical branches, paperwork, and hidden fees for an elegant digital experience and supreme savings. Giving people the power to live and bank their way is what gets us out of bed in the morning and inspires the work that we do.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;We are headquartered in Berlin with offices in multiple cities across Europe, including Vienna and Barcelona, and a 1,500-strong team of more than 80 nationalities.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Sounds good? Apply now for this position.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Equal Opportunities:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We recognize that our strength lies in our people and the varied perspectives they bring to our workforce. We strive to build talented and diverse teams to drive our business success and empower our people to reach their full potential.&lt;/p&gt;
&lt;p&gt;We genuinely welcome and encourage applications from people of all backgrounds, cultures, genders, sexual orientations, abilities, neurodiversities, and ages. We&#39;re committed to creating an inclusive workspace where everyone feels valued and respected, free from harassment and discrimination. If there&#39;s anything you need to make the application process work for you, please let us know by reaching out to candidate.exp@n26.com.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Visit our&lt;a href=&quot;https://n26.com/en-eu/diversity-and-inclusion&quot;&gt; website&lt;/a&gt; to learn more about Diversity, Equity, &amp;amp; Inclusion at N26.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

battery-narvar:greenhouse:7217201.descriptionHtml:
&lt;p&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;strong&gt;Narvar&lt;/strong&gt; is growing! We are hiring a Senior Software Engineer II to build new products and improve all aspects of the Narvar platform. Data is at the core of our competitive advantage so the work you do has a large impact across the company, our business partners, and the lives of our end users.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Machine Learning Engineers at Narvar work across the stack. We are ‘full-stack’ ML Engineers. This means that we write production-level code and own machine learning operations for our teams.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h4&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Day-to-day&lt;/strong&gt;&lt;/span&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Design and deploy machine learning algorithms for use cases spanning e-commerce, consumer trends, markets, logistics, and new products&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Work on real-world consumer data for natural language processing, image classification, time series analysis, outlier detection, user modeling, etc&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Work with large unstructured data&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Be at the intersection of mathematics, machine learning, business, and computer science and impact millions of users through your work&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Multiply the effect of your data science and data team members by building frameworks, tools, and methodologies that the entire team use&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Provide thought leadership to a team through high quality write-ups, reviews, and a strong vision grounded in practical experience and a wider industry view&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;What we’re looking for&lt;/strong&gt;&lt;/span&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Strong machine learning skills.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Fluency in Python,&amp;nbsp;PyTorch, Tensorflow, Pandas, numpy, and machine learning packages&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Data Engineering skills and large data experience. You should have dealt with large amounts of data (TB) in a production setting, built world class data pipelines using cutting edge tools (e.g. Spark).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;10+ years of hands-on experience shipping models to production, working on a variety of problem spaces (eg: user modeling, spam classification, prediction, clustering etc)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;MS in Computer Science, Statistics, Math, Science (physical or social), Engineering or similar quantitative and computation field plus 5+ years of industry experience&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Strong software engineering and coding skills with the ability to write production quality code&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Strong understanding of probability &amp;amp; statistics, machine learning, and algorithms&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Experience with SQL and NoSQL databases&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Experience working with Linux, shell scripting&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Previous startup experience strongly preferred&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Bonus Points&lt;/strong&gt;&lt;/span&gt;&lt;/h4&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Experience implementing applications on Google Cloud Platform&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Experience with deep generative models or graph learning a plus.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Tag your application with your solution to an active / recently concluded Kaggle competition, to get ahead of the list :)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Experience leading a team of data and data scientists; Strong ability to multiply the effect of the team and the team members; excellent written communication; self-starter that can balance sophistication with practicality&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Why Narvar?&lt;/strong&gt;&lt;/span&gt;&lt;/h4&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;We&#39;re on a mission to simplify the everyday lives of consumers. Post-purchase is a critical phase of the customer journey. That&#39;s why we created Narvar - a platform focused on driving customer loyalty through seamless post-purchase experiences that allow retailers to retain, engage, and delight customers. If you&#39;ve ever bought something online, there&#39;s a good chance you&#39;ve used our platform!&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;From the hottest new direct-to-consumer companies to retail’s most renowned brands, Narvar works with GameStop, Neiman Marcus, Sonos, Nike, and 1300+ + other brands. With hubs in San Francisco, Atlanta, London, and Bangalore, we&#39;ve served over 125 million consumers worldwide across 10+ billion interactions, 38 countries, and 55 languages.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400; font-size: 10pt;&quot;&gt;Pioneering the post-purchase movement means navigating into the unknown. Our team thrives on this sense of adventure while nurturing a mindset of innovation. We&#39;re a home for big hearts and we leave our egos at the door. We work hard but we always make time to celebrate professional wins, baby showers, birthday parties, and everything in between.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;em&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We are an equal-opportunity employer and value diversity at our company. We do not discriminate on the basis of race, religion, color, national origin, gender, sexual orientation, age, marital status, veteran status, or disability status.&lt;/span&gt;&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;#LI-PR1&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;#LI-Remote&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Below is the estimated annual salary for this position and does not include the other components that make up a Narvar offer including: annual bonus, equity, and benefits.&lt;br&gt;&lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The range reflects the minimum and maximum target for new hire salaries for the position across the US. Within the range, individual compensation packages are based on factors unique to each candidate, including but not limited to, skill set, education and certifications, and work location.&amp;nbsp;&lt;/span&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Narvar Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$180,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$230,000 CAD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Please read our &lt;a href=&quot;https://corp.narvar.com/privacy-policy&quot; target=&quot;_blank&quot;&gt;Privacy Policy&lt;/a&gt;&lt;/em&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;&amp;nbsp;to learn what personal information we collect in connection with your job application, and how we may use and share it.&amp;nbsp;&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;

benchstrengthvc-bolo-2-e2ed0795-2c77-4e6.descriptionHtml:
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Hybrid&amp;nbsp; •&amp;nbsp; Full-Time&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;About Bolo AI&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:280,&amp;quot;335559739&amp;quot;:160}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Bolo AI is building the next-generation&amp;nbsp;AI&amp;nbsp;agentic platform for heavy industries&amp;nbsp;to make them faster, safer, and better.&amp;nbsp;We create an intelligent context layer across complex industrial data, enabling AI&amp;nbsp;agents&amp;nbsp;that reason, retrieve, and act across workflows spanning the field, office, and control center. Our customers include energy companies, utilities, refineries, and chemical operators who use our platform to replace weeks of manual analysis with intelligent systems that surface what matters.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:200}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our early customers are seeing&amp;nbsp;real results&amp;nbsp;— from catching critical equipment failures hiding in plain sight to automating production optimization workflows that were previously done in spreadsheets.&amp;nbsp;We are a small team backed by True Ventures,&amp;nbsp;Benchstrength, Accomplice, Analog Ventures, and Beat Ventures.&amp;nbsp;We are AI-native: we use AI agents internally across every function, and we expect everyone on the team to work that way.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:200}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;The Role&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:280,&amp;quot;335559739&amp;quot;:160}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are hiring a Strategic Account Executive to own the full sales cycle,&amp;nbsp;from generating&amp;nbsp;pipeline&amp;nbsp;to closing enterprise deals across the energy and industrial sector. You will work directly with the founder and founding team, shaping both the deals we pursue and the sales motion we build.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:200}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is the part of a company’s journey that defines what comes next&amp;nbsp;-&amp;nbsp;which industries we expand into, how we sell, and what repeatable growth looks like. You will source your own opportunities through events,&amp;nbsp;outbound, channel partners, and your network. You will build custom demos on real customer data, manage pilots hands-on, and close. The work you do here will compound: the deals, the playbook, and the relationships you build will shape Bolo AI for years. The role requires regular travel for customer meetings, pilots, and industry events.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:200}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;What&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;You’ll&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;&amp;nbsp;Do&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:280,&amp;quot;335559739&amp;quot;:160}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Identify&amp;nbsp;and pursue enterprise accounts across upstream oil and gas, midstream, refining, chemicals, and utilities&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Own the full sales cycle: prospecting, discovery, stakeholder navigation, pilot management, and close&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Generate pipeline through industry events, targeted outbound, channel partnerships, and your own network&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Build and deliver custom demos using real customer data,&amp;nbsp;not generic slide decks.&amp;nbsp;that show prospects exactly how the platform solves their problems&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;•&quot; data-font=&quot;&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;•&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Stay hands-on through pilots and POCs, working with our customer delivery team to hit milestones and convert to&amp;nbsp;multi-year&amp;nbsp;enterprise contracts&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
